import { Component, OnInit, inject } from '@angular/core';
import {
  FormBuilder,
  FormGroup,
  Validators,
  AbstractControl,
} from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { MessageService } from 'primeng/api';
import { finalize } from 'rxjs/operators';
import { AdminAuthService } from '../../../../../libs/openapi/src/api/admin-auth.service';
import { ApiAdminAuthResetPasswordPostRequest } from '../../../../../libs/openapi/src/model/api-admin-auth-reset-password-post-request';

@Component({
  selector: 'app-reset-password',
  templateUrl: './reset-password.component.html',
  styleUrls: ['./reset-password.component.scss'],
  providers: [MessageService],
})
export class ResetPasswordComponent implements OnInit {
  private fb = inject(FormBuilder);
  private route = inject(ActivatedRoute);
  private router = inject(Router);
  private adminAuthService = inject(AdminAuthService);
  private messageService = inject(MessageService);

  resetPasswordForm!: FormGroup;
  token: string | null = null;
  isSubmitting = false;

  ngOnInit(): void {
    // 建立表單，並設置驗證規則
    this.resetPasswordForm = this.fb.group(
      {
        password: [
          '',
          [
            Validators.required,
            Validators.minLength(8),
            this.createPasswordStrengthValidator(),
          ],
        ],
        confirmPassword: ['', Validators.required],
      },
      {
        validators: this.passwordMatchValidator,
      }
    );

    // 從URL獲取token參數
    this.token = this.route.snapshot.queryParamMap.get('token');

    // 如果沒有token，顯示錯誤並導向到登入頁面
    if (!this.token) {
      this.messageService.add({
        severity: 'error',
        summary: '無效連結',
        detail: '密碼重設連結無效或已過期，請重新申請',
      });

      // 延遲導航，讓用戶有時間看到錯誤消息
      setTimeout(() => {
        this.router.navigate(['/auth/login']);
      }, 3000);
    }
  }

  // 密碼強度驗證器
  createPasswordStrengthValidator() {
    return (control: AbstractControl): { [key: string]: boolean } | null => {
      const value: string = control.value;
      if (!value) {
        return null;
      }

      // 至少包含大寫、小寫和數字
      const hasUpperCase = /[A-Z]/.test(value);
      const hasLowerCase = /[a-z]/.test(value);
      const hasNumeric = /[0-9]/.test(value);

      const passwordValid = hasUpperCase && hasLowerCase && hasNumeric;

      return !passwordValid ? { passwordStrength: true } : null;
    };
  }

  // 確認密碼匹配驗證
  passwordMatchValidator(control: AbstractControl) {
    const password = control.get('password')?.value;
    const confirmPassword = control.get('confirmPassword')?.value;

    if (password !== confirmPassword) {
      control.get('confirmPassword')?.setErrors({ passwordMismatch: true });
      return { passwordMismatch: true };
    } else {
      // 只有在密碼匹配時，才清除特定的錯誤
      const confirmPasswordControl = control.get('confirmPassword');
      if (confirmPasswordControl?.hasError('passwordMismatch')) {
        // 獲取原始錯誤對象
        const errors = { ...confirmPasswordControl.errors };
        delete errors['passwordMismatch'];

        // 如果沒有其他錯誤，設為null，否則設置其他錯誤
        confirmPasswordControl.setErrors(
          Object.keys(errors).length ? errors : null
        );
      }

      return null;
    }
  }

  // 重設密碼
  onSubmit() {
    if (this.resetPasswordForm.invalid) {
      this.markFormGroupTouched(this.resetPasswordForm);
      return;
    }

    if (!this.token) {
      this.messageService.add({
        severity: 'error',
        summary: '無效請求',
        detail: '缺少重設密碼的Token',
      });
      return;
    }

    this.isSubmitting = true;
    const password = this.resetPasswordForm.get('password')?.value;

    const request: ApiAdminAuthResetPasswordPostRequest = {
      token: this.token,
      password: password,
    };

    this.adminAuthService
      .apiAdminAuthResetPasswordPost(request)
      .pipe(finalize(() => (this.isSubmitting = false)))
      .subscribe({
        next: () => {
          this.messageService.add({
            severity: 'success',
            summary: '成功',
            detail: '密碼已重設，請使用新密碼登入',
          });

          // 延遲導航，讓用戶有時間看到成功消息
          setTimeout(() => {
            this.router.navigate(['/auth/login']);
          }, 3000);
        },
        error: (error) => {
          let errorMessage = '密碼重設失敗，請稍後再試';

          if (error.error?.message) {
            errorMessage = error.error.message;
          } else if (error.message) {
            errorMessage = error.message;
          }

          this.messageService.add({
            severity: 'error',
            summary: '密碼重設失敗',
            detail: errorMessage,
          });
        },
      });
  }

  // 標記表單所有控件為已觸碰，顯示所有錯誤消息
  private markFormGroupTouched(formGroup: FormGroup) {
    Object.values(formGroup.controls).forEach((control) => {
      control.markAsTouched();

      if (control instanceof FormGroup) {
        this.markFormGroupTouched(control);
      }
    });
  }
}
